import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"12、【否】 坤下乾上","description":"周易口诀义 - 12、【否】 坤下乾上","frontmatter":{"title":"12、【否】 坤下乾上","description":"周易口诀义 - 12、【否】 坤下乾上"},"headers":[],"relativePath":"zh/classics/koujueyi/014.md","filePath":"zh/classics/koujueyi/014.md"}'),r={name:"zh/classics/koujueyi/014.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_12、【否】-坤下乾上" tabindex="-1">12、【否】 坤下乾上 <a class="header-anchor" href="#_12、【否】-坤下乾上" aria-label="Permalink to “12、【否】 坤下乾上”">​</a></h1><p>彖曰：「否之匪人，不利君子贞，大往小来」，则是天地不交而万物不通也，上下不交而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子，小人道长，君子道消也。</p><p>象曰：天地不交，否。君子以俭德辟难，不可荣以禄。</p><p>初六：拔茅茹，以其汇，贞吉亨。</p><p>象曰：拔茅贞吉，志在君也。</p><p>六二：包承，小人吉，大人否，亨。</p><p>象曰：「大人否亨」，不乱群也。</p><p>六三：包羞。象曰：「包羞」，位不当也。</p><p>九四：有命无咎，畴离祉。</p><p>象曰：「有命无咎」，志行也。</p><p>九五：休否，大人吉。其亡其亡，繋于苞桑。</p><p>象曰：大人之吉，位正当也。</p><p>上九：倾否，先否后喜。</p><p>象曰：否终则倾，何可长也。</p><p>解读</p><p>「否之匪人，不利君子贞」者，否以上下不交，君臣不孚，故为闭塞之义也。当否塞之时，小人道长，非是君子德通之时，故曰「匪人」也。小人侵陵君子，邪道乃兴，故不利君子而为正，故曰「不利君子贞」也。象曰：「天地不交，否」者，天气上，地气下，二气不相交通，故曰否闭之象也。「君子以俭德避难，不可荣以禄」者，言君子当否闭之时，不可处宠求安，故以节俭为德，避于小人之难，不可荣其身，食以禄也。</p><p>「初六，拔茅茹，以其汇，贞吉，亨」者，夫柔之为道，必依于刚；弱之为道，必亲于强，故独处须托之以君子。今初六体既柔劣，不事干进，但以众类亲比于上，既不往謟，守正应上，所以获正之吉也。</p><p>「六二，包承，小人吉，大人否，亨」者，六二以柔顺之质，但施包纳，承顺于君，故曰「包承」也。处否闭之时，是小人道长，故小人获吉；大人当否闭之时，虽复小人为乱，但防之以道，遏绝小人，所以获亨通也，故曰「大人否，亨」也。</p><p>「六三包羞」者，盖耻辱也。六三以謟媚之身，而为小人之行，所为之事，皆包羞耻故也。</p><p>「九四，有命，无咎，畴离祉」者，夫君子亲于小人，则有耻累至焉。今九四若有招命于初，是亲于小人，祸咎必至。只为初六修正，不敢为謟，故九四命之则无咎，故曰「有命无咎」。既有招命初六，初六必当受福，故曰「畴离祉」也。畴，初也，谓初六；离，著也；祉，福也，谓九四命之，因此招命，得其福也。</p><p>「九五，休否，大人吉。其亡其亡，繋于苞桑」者，休，美也；处否闭之时，而居尊位，以休美之德，悦谕小人，使小人不妄为非，故曰「休否」也。有斯美德，悦服小人，若非大德之人，拯世之君，即不能获吉，故曰「大人吉」也。以小人道长之时，恐有危乱及身，故丁宁戒惧，虑其灭亡。再言之者，忧惧之甚，故云「其亡其亡」也。既虑危乱，故必「繋于苞桑」之固矣。苞，本也；桑者根多，固有牢固之义，故曰「繋苞桑」也。</p><p>「上九，倾否，先否后喜」者，处否之极，泰道将至，故倾弃其否，以至通泰，故曰「倾否」。先塞后通，故后有喜庆，故曰「先否后喜」也。</p>',22)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
